function check(value: boolean, message: string): void { if (!value) throw new Error(message); }
async function rejected(action: () => Promise<unknown>): Promise<void> { let failed: boolean = false; try { await action(); } catch (error: unknown) { if (!(error instanceof Error)) throw error; failed = true; } check(failed, "거부해야 할 요청이 성공했어요."); }
export async function runLibrarianFixture(request: Request, environment: Readonly<{ DB: D1Database; BUCKET: R2Bucket }>, verifyConsumer: (db:D1Database,bucket:R2Bucket,owner:SiteIdentity,scopeId:string)=>Promise<readonly string[]>): Promise<Response> {
  const { DB, BUCKET } = environment;
  const { owner, id } = await initializeUploadFixture(DB, request);
  const upload = await uploadMaterialBody(DB, BUCKET, owner, id, 1, request);
  await completeMaterialTransfer(DB, BUCKET, owner, id, upload.version, { pdf, jpeg }, new AbortController().signal);
  const transfer = await getMaterialTransfer(DB, owner, id);
  const advisor = await confirmedPlanFixture(DB, owner); const units = await listConfirmedUnits(DB, owner); const unit = units.find((item): boolean => item.prerequisiteUnitIds.length === 0);
  check(unit !== undefined && advisor.confirmedPlanVersionId !== null, "확정 단원이 없어요."); if (!unit) throw new Error("단원 누락");
  const cmd = (expectedVersion: number) => ({ owner, requestKey: crypto.randomUUID(), expectedVersion });
  const selection = buildSelection(materialFileReference(transfer), "1", "");
  await saveExtractionSelection(DB, cmd(0), transfer, selection);
  const page = (await listExtractionPages(DB, owner, transfer.materialId, 1))[0];
  const proof = await requireExtractionPage(DB, BUCKET, owner, transfer.materialId, 1, 1);
  const text: string = "저자: ALTER. 출처: 자체 시험 자료. 판본: fixture-v1. 분수는 전체를 같은 크기로 나눈 부분입니다. 분모는 전체 조각 수, 분자는 선택한 조각 수입니다. 네 조각 중 하나는 1/4입니다. 연습: 같은 크기의 여덟 조각 중 세 조각을 분수로 써 보세요.";
  const result: PageResult = { filePage: 1, method: "text-layer", status: "complete", width: 612, height: 792, rotation: 0, segments: [{ id: "s0", kind: "text", text, bounds: { x: 0,y: 0,width: 1,height: 1 }, transform: null, uncertain: false, reason: null }], error: null, requiresConfirmation: true };
  await saveTextExtraction(DB, cmd(page.version), proof, page, result);
  const extracted = await getExtractionPage(DB, owner, page.id);
  if (!extracted.resultId) throw new Error("결과 누락");
  await confirmExtractionSegments(DB, cmd(extracted.version), proof, extracted, { selectionRevision: 1,filePage: 1,expectedVersion: extracted.version,resultId: extracted.resultId,segmentIds: ["s0"],printedPage: "i",comparedWithOriginal: true });
  const confirmed = await getExtractionPage(DB, owner, page.id);
  await createExtractionSource(DB, cmd(confirmed.version), proof, confirmed, "s0");
  const sourceId = await DB.prepare("SELECT source_id FROM extraction_sources WHERE owner_id=? AND result_id=?").bind(owner.userId, confirmed.resultId).first<string>("source_id"); if (!sourceId) throw new Error("출처 누락");
  const input = linkInput.parse({ id: recordId.parse(crypto.randomUUID()), planVersionId: unit.planVersionId, unitId: unit.unitId, materialId: transfer.materialId, toc: "분수의 의미", sourceRefIds: [sourceId], bibliography: { author: "ALTER", origin: "자체 시험 자료", checked: true, evidenceSourceId: sourceId }, readingMinutes: 5 });
  const command = cmd(1); await createMaterialLink(DB, BUCKET, command, input); await createMaterialLink(DB, BUCKET, command, input);
  const link = await getMaterialLink(DB, owner, input.id);
  check(link.metadata.edition === "fixture-v1" && (await inspectMaterialLink(DB, BUCKET, owner, link)).valid, "판본·출처 연결 실패");
  await rejected(() => getMaterialLink(DB, { realm: "sites", userId: "other" }, input.id));
  await rejected(() => createMaterialLink(DB, BUCKET, cmd(1), { ...input, id: recordId.parse(crypto.randomUUID()), unitId: recordId.parse("00000000-0000-4000-a000-000000000000") }));
  await rejected(() => createMaterialLink(DB, BUCKET, cmd(1), { ...input, id: recordId.parse(crypto.randomUUID()), bibliography: { ...input.bibliography, author: "없는 저자" } }));
  const external = linkInput.parse({ ...input, id: crypto.randomUUID(), bibliography: { author: "외부 저자", origin: "외부 출판사", checked: true, evidenceSourceId: null, external: { id: crypto.randomUUID(), kind: "user-statement", title: "외부 교재", edition: null, url: null, evidence: "사용자가 외부 교재, 외부 저자, 외부 출판사를 확인했습니다. 판본은 미확인입니다." } } });
  await createMaterialLink(DB, BUCKET, cmd(1), external);
  const savedExternal = await getMaterialLink(DB, owner, external.id);
  check(savedExternal.bibliography.external?.edition === null && savedExternal.sourceRefIds[0] === sourceId, "외부 서지가 본문을 바꾸거나 판본을 확정했어요.");
  await rejected(() => createMaterialLink(DB, BUCKET, cmd(1), { ...external, id: recordId.parse(crypto.randomUUID()), bibliography: { ...external.bibliography, author: "다른 저자" } }));
  const unverified = { ...input, id: recordId.parse(crypto.randomUUID()), sourceRefIds: [], bibliography: { author: "", origin: "", checked: false, evidenceSourceId: null } }; await createMaterialLink(DB, BUCKET, cmd(1), unverified);
  check(!(await inspectMaterialLink(DB, BUCKET, owner, await getMaterialLink(DB, owner, unverified.id))).valid, "본문 없는 연결이 검증 상태예요.");
  await DB.prepare("CREATE TRIGGER fixture_link_failure BEFORE INSERT ON librarian_link_sources BEGIN SELECT RAISE(ABORT,'fixture_link_failure'); END").run();
  const failed = { ...input, id: recordId.parse(crypto.randomUUID()) }; await rejected(() => createMaterialLink(DB, BUCKET, cmd(1), failed)); await rejected(() => getMaterialLink(DB, owner, failed.id)); await DB.prepare("DROP TRIGGER fixture_link_failure").run();
  await rejected(() => DB.prepare("DELETE FROM librarian_links WHERE owner_id=?").bind(owner.userId).run());
  const scopeValue = scopeInput.parse({ id: crypto.randomUUID(),planVersionId: unit.planVersionId,unitId: unit.unitId,date: "2026-10-24",availableMinutes: 30,questionMinutes: 5,practiceMinutes: 10,linkIds: [input.id] });
  const startCommand = cmd(1); await createStudyScope(DB, BUCKET, startCommand, scopeValue); await createStudyScope(DB, BUCKET, startCommand, scopeValue);
  const start = await getStudyScope(DB, owner, scopeValue.id);
  await rejected(() => getStudyScope(DB, { realm: "sites",userId: "other" }, scopeValue.id));
  await rejected(() => readTutorBundle(DB, BUCKET, owner, scopeValue.id));
  const beginCommand = cmd(start.version); await beginStoredScopeEvaluation(DB, BUCKET, beginCommand, scopeValue.id); await beginStoredScopeEvaluation(DB, BUCKET, beginCommand, scopeValue.id);
  const evaluating = await getStudyScope(DB, owner, scopeValue.id); const output = librarianOutputFixture(evaluating);
  const ai = librarianRuntimeFixture(DB,owner,scopeValue.id);
  await DB.prepare("CREATE TRIGGER fixture_ai_saved_failure BEFORE INSERT ON scope_events WHEN NEW.version=3 BEGIN SELECT RAISE(ABORT,'fixture_ai_saved_failure'); END").run();
  await rejected(() => processLibrarianAi(ai.runtime,BUCKET,owner,scopeValue.id,ai.pricing,dispatchLibrarian,new AbortController().signal));
  check(ai.generations() === 1 && (await getStudyScope(DB,owner,scopeValue.id)).phase === "evaluating", "AI 저장 실패 상태 불일치");
  await DB.prepare("DROP TRIGGER fixture_ai_saved_failure").run();
  await processLibrarianAi(ai.runtime,BUCKET,owner,scopeValue.id,ai.pricing,dispatchLibrarian,new AbortController().signal);
  await saveScopeEvaluation(DB, BUCKET, owner, evaluating, output);
  check(ai.generations() === 1, "저장된 AI 결과를 재호출했어요.");
  const proposed = await getStudyScope(DB, owner, scopeValue.id); check(proposed.phase === "proposed" && proposed.selection?.minutes === 20, "제안 범위 또는 시간이 달라요.");
  const choices = { reviewedVersion: proposed.version,reviewedSources: true as const,acceptedTime: true as const,acceptedAssessment: true as const };
  await DB.prepare("CREATE TRIGGER fixture_scope_failure BEFORE INSERT ON scope_events WHEN NEW.version=4 BEGIN SELECT RAISE(ABORT,'fixture_scope_failure'); END").run();
  await rejected(() => confirmStoredScope(DB, BUCKET, cmd(proposed.version), proposed.input.id, choices));
  check((await getStudyScope(DB, owner, scopeValue.id)).phase === "proposed", "일부 확정이 남았어요.");
  await DB.prepare("DROP TRIGGER fixture_scope_failure").run();
  const confirmationCommand = cmd(proposed.version); await confirmStoredScope(DB, BUCKET, confirmationCommand, proposed.input.id, choices); await confirmStoredScope(DB, BUCKET, confirmationCommand, proposed.input.id, choices);
  await rejected(() => confirmStoredScope(DB, BUCKET, cmd(proposed.version), proposed.input.id, choices));
  const bundle = await readTutorBundle(DB, BUCKET, owner, scopeValue.id);
  check(bundle.sources[0].evidence === text && bundle.sources[0].printedPage === "i" && bundle.question.sourceRefIds[0] === sourceId && bundle.exercise.sourceRefIds[0] === sourceId && bundle.unit.newConditionCriterion === unit.newConditionCriterion, "Tutor 묶음 누락 또는 원문 불일치");
  await rejected(() => DB.prepare("DELETE FROM scope_events WHERE owner_id=?").bind(owner.userId).run());
  const rollbackId = recordId.parse(crypto.randomUUID());
  await DB.prepare("CREATE TRIGGER fixture_scope_start_failure BEFORE INSERT ON scope_events WHEN NEW.version=1 BEGIN SELECT RAISE(ABORT,'fixture_scope_start_failure'); END").run();
  await rejected(() => createStudyScope(DB, BUCKET, cmd(1), { ...scopeValue,id: rollbackId })); await rejected(() => getStudyScope(DB, owner, rollbackId));
  await DB.prepare("DROP TRIGGER fixture_scope_start_failure").run();
  const consumerChecks=await verifyConsumer(DB,BUCKET,owner,scopeValue.id);
  await saveExtractionCorrection(DB, cmd(confirmed.version), proof, confirmed, correctedPage(confirmed, { selectionRevision: 1, filePage: 1,expectedVersion: confirmed.version,resultId: confirmed.resultId!,segments: [{ id: "s0", text: "수정된 원문" }] }));
  check(!(await inspectMaterialLink(DB, BUCKET, owner, link)).valid, "정정 후 이전 구간을 계속 사용해요.");
  await rejected(() => readTutorBundle(DB, BUCKET, owner, scopeValue.id));
  await DB.prepare("INSERT INTO plan_versions VALUES (?,?,?,?,?,?,?)").bind(owner.userId, crypto.randomUUID(), unit.planId, unit.courseId, 2, JSON.stringify({ objective: "새 목표",unitIds: [unit.unitId],minutesPerWeek: 60 }), Date.now()).run();
  await rejected(() => readConfirmedUnit(DB, owner, unit.planVersionId, unit.unitId));
  await rejected(() => requireCurrentScope(DB, BUCKET, owner, proposed));
  check((await DB.prepare("PRAGMA foreign_key_check").all()).results.length === 0, "참조 무결성 실패");
  return Response.json({ status: "passed", environment: "local-workerd-d1-r2", checks: [...consumerChecks,"confirmed-plan-and-unit-binding", "edition-and-source-span", "owner-and-missing-unit-denied", "bibliography-citation-required", "external-bibliography-persisted-with-unknown-edition-and-original-source", "unverified-body-visible", "idempotency-and-partial-write-rollback", "immutable-link-history", "source-correction-invalidates-link", "new-plan-requires-relink", "real-sdk-mock-ai-reservation-and-saved-result-recovery", "scope-proposal-confirmation-separation", "scope-idempotency-and-concurrent-version-rejection", "scope-start-and-confirm-rollback", "confirmed-tutor-bundle-exact-source-and-both-criteria", "correction-invalidates-tutor-bundle"] });
}
async function fetch(request:Request,environment:Readonly<{DB:D1Database;BUCKET:R2Bucket}>):Promise<Response> { return runLibrarianFixture(request,environment,async ():Promise<readonly string[]>=>[]); }
const worker = { fetch };
export default worker;
